mapper.select:
SELECT id, conversation_id, run_id, projection_key, role, status, content, tool_call_id, tool_name, tool_status, first_sequence, last_sequence, created_at, updated_at, created_by, updated_by FROM manga_creative_message
WHERE conversation_id = #{conversationId}
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

SELECT m.id, m.conversation_id, m.run_id, m.projection_key, m.role, m.status, m.content, m.tool_call_id, m.tool_name, m.tool_status, m.first_sequence, m.last_sequence, m.created_at, m.updated_at, m.created_by, m.updated_by FROM manga_creative_message m
JOIN manga_creative_run r ON r.run_id = m.run_id
WHERE m.conversation_id = #{conversationId} AND m.id > #{afterId}
  AND r.status = 'COMPLETED' AND m.role IN ('USER', 'ASSISTANT')
ORDER BY m.id ASC LIMIT #{limit}

mapper.update:
UPDATE manga_creative_message SET status = #{status}, last_sequence = #{sequence},
    tool_status = CASE WHEN role = 'TOOL' AND tool_status = 'RUNNING' THEN #{toolStatus} ELSE tool_status END,
    updated_by = #{actor}
WHERE run_id = #{runId}
